<!-- 文件职责 / File responsibility: 独立编辑耳朵形状、颜色和注册表发光范围。 / Independently edits ear shape, colors, and registry-driven glow. -->
<script setup lang="ts">
import StudioNumericControl from './StudioNumericControl.vue';import { PET_STUDIO_PART_OPTIONS,type RichEarStyle } from '~/domain/pet-studio-phase2';import { usePetAppearanceStore } from '~/stores/pet-appearance';const store=usePetAppearanceStore();const recipe=computed(()=>store.recipe);function change(event:Event){store.checkpoint();store.patchParts({ears:(event.target as HTMLSelectElement).value as RichEarStyle})}
</script>
<template><section class="card"><h3>耳朵多色方案</h3><p>外耳、内耳、耳尖与内耳发光独立配置。</p><label>耳朵形状<select :value="recipe.parts.ears" @change="change"><option v-for="item in PET_STUDIO_PART_OPTIONS.ears" :key="item.id" :value="item.id">{{item.label}}</option></select></label><div class="colors"><label>外耳<input v-model="recipe.customization.colors.earOuter" type="color" @focus="store.checkpoint" @input="recipe.earDesign.outerColor=recipe.customization.colors.earOuter;store.markDirty()"></label><label>内耳<input v-model="recipe.customization.colors.earInner" type="color" @focus="store.checkpoint" @input="recipe.earDesign.innerColor=recipe.customization.colors.earInner;store.markDirty()"></label><label>耳尖<input v-model="recipe.customization.colors.earTip" type="color" @focus="store.checkpoint" @input="recipe.earDesign.tipColor=recipe.customization.colors.earTip;store.markDirty()"></label><label>内耳光色<input v-model="recipe.earDesign.innerGlowColor" type="color" @focus="store.checkpoint" @input="store.markDirty"></label></div><label class="check"><input v-model="recipe.earDesign.innerGlowEnabled" type="checkbox" @focus="store.checkpoint" @change="store.markDirty">启用内耳发光</label><StudioNumericControl path="earDesign.innerGlowIntensity" :model-value="recipe.earDesign.innerGlowIntensity" :disabled="!recipe.earDesign.innerGlowEnabled" @update:model-value="recipe.earDesign.innerGlowIntensity=$event"/></section></template>
<style scoped>.card{display:grid;gap:9px;padding:11px;border:1px solid #ffffff18;border-radius:11px;background:#ffffff08}.card h3,.card p{margin:0}.card p{color:#9da6c8;font-size:10px}.card label{display:grid;gap:5px;color:#bbc2dc;font-size:11px}.card select{min-height:38px;border:1px solid #ffffff22;border-radius:9px;padding:7px;color:#fff;background:#111526}.colors{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.colors input{width:100%;height:36px;border:0;background:transparent}.check{display:flex!important;align-items:center!important;gap:7px}</style>
